package com.smartvpn.acceptance;

import android.app.Activity;
import android.net.*;
import android.os.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;

// Runs under a different UID from the VPN. A direct route to the documentation
// address cannot return the nonce generated by the loopback fixture.
public final class Peer extends Activity {
    private static void verifyReply(byte[] request, byte[] reply) throws IOException {
        for (int i = 0; i < request.length; i++)
            if ((byte)(request[i] ^ 0x5a) != reply[i]) throw new IOException("wrong reply at byte " + i);
    }

    private static void checkPackets() throws IOException {
        InetSocketAddress target = new InetSocketAddress("198.51.100.61", 18061);
        java.security.SecureRandom rng = new java.security.SecureRandom();
        byte[] request = new byte[32768];
        rng.nextBytes(request);
        try (Socket socket = new Socket()) {
            socket.connect(target, 8000);
            socket.setSoTimeout(10000);
            socket.getOutputStream().write(request);
            byte[] response = new byte[request.length];
            new DataInputStream(socket.getInputStream()).readFully(response);
            verifyReply(request, response);
        }
        request = new byte[1024];
        rng.nextBytes(request);
        try (DatagramSocket socket = new DatagramSocket()) {
            socket.connect(target);
            socket.setSoTimeout(8000);
            socket.send(new DatagramPacket(request, request.length));
            byte[] response = new byte[request.length+1];
            DatagramPacket reply = new DatagramPacket(response, response.length);
            socket.receive(reply);
            if (reply.getLength() != request.length) throw new IOException("wrong UDP payload size");
            verifyReply(request, response);
        }
    }
    private static void streamBatch(int count) throws Exception {
        java.util.concurrent.ExecutorService pool = java.util.concurrent.Executors.newFixedThreadPool(count);
        java.util.concurrent.CyclicBarrier ready = new java.util.concurrent.CyclicBarrier(count);
        java.util.List<java.util.concurrent.Future<Void>> tasks = new java.util.ArrayList<>();
        try {
            for (int i=0; i<count; i++) tasks.add(pool.submit(() -> {
                byte[] data = new byte[512];
                new java.security.SecureRandom().nextBytes(data);
                try (Socket socket = new Socket()) {
                    socket.connect(new InetSocketAddress("198.51.100.61",18061),8000);
                    socket.setSoTimeout(12000);
                    socket.getOutputStream().write(data);
                    byte[] reply = new byte[data.length];
                    new DataInputStream(socket.getInputStream()).readFully(reply);
                    verifyReply(data, reply);
                    ready.await(12, java.util.concurrent.TimeUnit.SECONDS);
                }
                return null;
            }));
            for (java.util.concurrent.Future<Void> task : tasks) task.get();
        } finally {
            pool.shutdownNow();
        }
    }
    @Override
    public void onCreate(Bundle state) {
        super.onCreate(state);
        new Thread(() -> {
            String run = getIntent().getStringExtra("nonce");
            Bundle result = new Bundle();
            try {
                ConnectivityManager cm = getSystemService(ConnectivityManager.class);
                boolean underlay = getIntent().getBooleanExtra("underlay", false);
                long deadline = SystemClock.elapsedRealtime() + 5000;
                while (true) {
                    NetworkCapabilities caps = cm.getNetworkCapabilities(cm.getActiveNetwork());
                    if (caps != null && caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN) != underlay)
                        break;
                    if (SystemClock.elapsedRealtime() >= deadline)
                        throw new IOException(underlay ? "underlying network timeout" : "VPN transport timeout");
                    Thread.sleep(50);
                }
                if (!underlay) {
                    if (getIntent().getBooleanExtra("revoke", false)) {
                        if (VpnService.prepare(this) != null)
                            throw new IOException("peer requires test VPN consent");
                    } else if (getIntent().getBooleanExtra("sessionTest", false)) {
                        streamBatch(6);
                        Thread.sleep(40000);
                        streamBatch(1);
                    } else if (getIntent().getBooleanExtra("packetTest", false)) {
                        checkPackets();
                    } else {
                        String nonce = getIntent().getStringExtra("nonce");
                        try (Socket s = new Socket()) {
                            s.connect(new InetSocketAddress("198.51.100.61", 18061), 8000);
                            s.setSoTimeout(8000);
                            s.getOutputStream().write(
                                (nonce + "\n").getBytes(StandardCharsets.US_ASCII));
                            String line =
                                new BufferedReader(new InputStreamReader(s.getInputStream()))
                                    .readLine();
                            if (!("TUN " + nonce).equals(line))
                                throw new IOException("wrong TUN reply");
                        }
                    }
                }
            } catch (Exception e) {
                result.putString("error", e.toString());
            }
            android.util.Log.i("SmartVPNPeer", run + " " + result.getString("error", "PASS"));
            runOnUiThread(this::finish);
        }).start();
    }
}
